const upsertStockForecastSnapshot = `-- name: UpsertStockForecastSnapshot :one

WITH demote AS (
    UPDATE stock_forecasts AS sf
    SET is_latest = false
    WHERE $1::bool
      AND sf.organization_id = $2
      AND sf.product_id = $3
      AND sf.computed_on <> $4::date
    RETURNING 1
), input AS (
    SELECT
        $2::bigint AS organization_id,
        $5::bigint AS brand_id,
        $3::bigint AS product_id,
        $4::date AS computed_on,
        $1::bool AS is_latest,
        $6::int AS on_hand_qty,
        $7::numeric AS on_hand_meters,
        $8::numeric AS avg_daily_30,
        $9::numeric AS avg_daily_90,
        $10::numeric AS seasonality_factor,
        $11::numeric AS avg_meters_per_vehicle,
        $12::numeric AS vehicles_left,
        $13::numeric AS days_left,
        $14::date AS depletion_date,
        $15::int AS data_days,
        $16::text AS status,
        $17::int AS suggested_qty,
        $18::numeric AS suggested_meters
)
INSERT INTO stock_forecasts (
    organization_id, brand_id, product_id, computed_on, is_latest,
    on_hand_qty, on_hand_meters, avg_daily_30, avg_daily_90,
    seasonality_factor, avg_meters_per_vehicle, vehicles_left, days_left,
    depletion_date, data_days, status, suggested_qty, suggested_meters
)
SELECT organization_id, brand_id, product_id, computed_on, is_latest,
       on_hand_qty, on_hand_meters, avg_daily_30, avg_daily_90,
       seasonality_factor, avg_meters_per_vehicle, vehicles_left, days_left,
       depletion_date, data_days, status, suggested_qty, suggested_meters
FROM input
WHERE (SELECT COUNT(*) FROM demote) >= 0
ON CONFLICT (organization_id, product_id, computed_on) DO UPDATE
SET brand_id = EXCLUDED.brand_id,
    is_latest = EXCLUDED.is_latest,
    on_hand_qty = EXCLUDED.on_hand_qty,
    on_hand_meters = EXCLUDED.on_hand_meters,
    avg_daily_30 = EXCLUDED.avg_daily_30,
    avg_daily_90 = EXCLUDED.avg_daily_90,
    seasonality_factor = EXCLUDED.seasonality_factor,
    avg_meters_per_vehicle = EXCLUDED.avg_meters_per_vehicle,
    vehicles_left = EXCLUDED.vehicles_left,
    days_left = EXCLUDED.days_left,
    depletion_date = EXCLUDED.depletion_date,
    data_days = EXCLUDED.data_days,
    status = EXCLUDED.status,
    suggested_qty = EXCLUDED.suggested_qty,
    suggested_meters = EXCLUDED.suggested_meters
RETURNING id, uuid, organization_id, brand_id, product_id, computed_on, is_latest, on_hand_qty, on_hand_meters, avg_daily_30, avg_daily_90, seasonality_factor, avg_meters_per_vehicle, vehicles_left, days_left, depletion_date, data_days, status, suggested_qty, suggested_meters, created_at, updated_at
`

